module vacation_planner(\n    input clk,\n    input rst_n,\n    input start,\n    input [4:0] L,\n    input [15:0] trans_matrix [63:0],\n    output reg [5:0] T,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE     = 2'd0;\n    localparam [1:0] INIT     = 2'd1;\n    localparam [1:0] UPDATE   = 2'd2;\n    localparam [1:0] DONE_ST  = 2'd3;\n\n    reg [1:0] current_state, next_state;\n    reg [4:0] day_counter;\n    reg [31:0] state_reg[0:7];   // Q8.8 fixed-point states\n    reg [31:0] next_state_reg[0:7];\n    reg found;\n    wire [5:0] L_plus_9;\n\n    // Combinational calculations\n    assign L_plus_9 = L + 5'd9;\n\n    // FSM state transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_state <= IDLE;\n            day_counter <= 5'd0;\n            T <= 6'b111111;\n            done <= 1'b0;\n            found <= 1'b0;\n        end else begin\n            current_state <= next_state;\n\n            case (current_state)\n                INIT: begin\n                    day_counter <= 5'd0; // Start counting from day 0 (initial state)\n                end\n                \n                UPDATE: begin\n                    if (day_counter >= L && day_counter <= L_plus_9) begin\n                        if (state_reg[7] >= 32'd61952 && state_reg[7] <= 32'd62464 && !found) begin\n                            T <= {1'b0, day_counter};\n                            found <= 1'b1;\n                        end\n                    end\n                    \n                    // Apply next state\n                    day_counter <= day_counter + 1;\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                end\n            endcase\n\n            // State register update (applies to INIT and UPDATE)\n            if (current_state == INIT) begin\n                state_reg[0] <= 32'd65536; // 256 << 8 = 65536\n                state_reg[1] <= 32'd0;\n                state_reg[2] <= 32'd0;\n                state_reg[3] <= 32'd0;\n                state_reg[4] <= 32'd0;\n                state_reg[5] <= 32'd0;\n                state_reg[6] <= 32'd0;\n                state_reg[7] <= 32'd0;\n            end else if (current_state == UPDATE) begin\n                state_reg[0] <= next_state_reg[0];\n                state_reg[1] <= next_state_reg[1];\n                state_reg[2] <= next_state_reg[2];\n                state_reg[3] <= next_state_reg[3];\n                state_reg[4] <= next_state_reg[4];\n                state_reg[5] <= next_state_reg[5];\n                state_reg[6] <= next_state_reg[6];\n                state_reg[7] <= next_state_reg[7];\n            end\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        case (current_state)\n            IDLE: next_state = (start) ? INIT : IDLE;\n            INIT: next_state = UPDATE;\n            UPDATE: next_state = ((day_counter + 1) > L_plus_9) ? DONE_ST : UPDATE;\n            DONE_ST: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Next state vector computation\n    integer i, j;\n    always @(*) begin\n        for (j = 0; j < 8; j = j + 1) begin\n            reg [55:0] sum_j;\n            reg [47:0] product;\n            sum_j = 56'd0;\n\n            for (i = 0; i < 8; i = i + 1) begin\n                product = state_reg[i] * trans_matrix[i*8 + j];\n                sum_j = sum_j + product;\n            end\n\n            next_state_reg[j] = sum_j >> 8;\n        end\n    end\n\nendmodule